"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[5836],{5836:e=>{e.exports=JSON.parse('{"slug":"inflyaciya-uskorilas-ohlazhdenie-ekonomiki","locale":"es","title":"La inflaci\xf3n semanal rusa acelera por segunda semana y las expectativas llegan al 14,2%","description":"La inflaci\xf3n semanal pasa del 0,02% al 0,12% en tres semanas y las expectativas suben al 14,2%. Por qu\xe9 importa para la decisi\xf3n del Banco de Rusia del 23 de octubre.","blocks":[{"id":"b001","kind":"paragraph","text":"Del 22 al 28 de septiembre de 2026, los precios rusos subieron un 0,12%. La semana previa fue un 0,06% y la anterior, un 0,02%. Es el avance semanal m\xe1s r\xe1pido desde finales de julio. Si se repitiera el 0,12% cada semana, el a\xf1o dar\xeda cerca del 6,4% (1,0012 elevado a 52), frente a la meta del 4%. Una semana prueba poco, pero tres aceleraciones seguidas ya son visibles."},{"id":"b002","kind":"paragraph","text":"Las hortalizas de oto\xf1o a\xfan abaratan la cesta, pero cada vez menos: la patata baj\xf3 un 3,2% en la \xfaltima semana, frente al 3,4% previo. A la vez, los huevos subieron un 1,9% y el trigo sarraceno y el mijo un 0,8%. La inflaci\xf3n interanual al 28 de septiembre ronda el 6,25%; desde enero suma un 4,93%, frente al 4,29% del mismo periodo de 2025."},{"id":"b003","kind":"paragraph","text":"El Banco de Rusia estim\xf3 en septiembre la inflaci\xf3n persistente de agosto, sin saltos puntuales, en un 5–6% anualizado. El verano estuvo marcado por el combustible: julio registr\xf3 un 11,7% anualizado desestacionalizado y agosto un 6,9%. El shock pas\xf3, pero no se lleg\xf3 a la meta del 4%, y el tipo oficial sigue alto, en el 14%."},{"id":"b004","kind":"paragraph","text":"Los tipos altos enfr\xedan la econom\xeda: el cr\xe9dito caro reduce el gasto y frena los precios. Funciona mejor si la gente cree que la inflaci\xf3n bajar\xe1. En septiembre se esperaba un 14,2% para el pr\xf3ximo a\xf1o, frente al 13,7% de agosto, aunque la inflaci\xf3n efectiva ronda el 6,25%. Si esperas un 14%, un tipo del 14% apenas disuade: comprar ahora parece mejor que ahorrar. Son expectativas inflacionarias y el Banco de Rusia advierte que pueden impedir la desaceleraci\xf3n."},{"id":"b005","kind":"paragraph","text":"No sabemos si comienza una aceleraci\xf3n o es un repunte puntual. Rosstat publicar\xe1 septiembre el 9 de octubre y el banco central decidir\xe1 el 23. Para el ciudadano, los dep\xf3sitos a\xfan superan los precios: el promedio m\xe1ximo de los 10 mayores bancos al cierre de septiembre es del 13,05%, frente al 6,25% de inflaci\xf3n. Endeudarse esperando un recorte r\xe1pido es arriesgado; esperar indefinidamente tambi\xe9n cuesta porque los precios siguen aumentando."},{"id":"b006","kind":"heading","text":"\xbfCu\xe1l es la inflaci\xf3n rusa a finales de septiembre de 2026?"},{"id":"b007","kind":"paragraph","text":"Al 28 de septiembre, ronda el 6,25% anual y el 4,93% desde enero. La \xfaltima semana suma un 0,12%, el mayor avance desde finales de julio. Rosstat publicar\xe1 el dato mensual oficial el 9 de octubre."},{"id":"b008","kind":"heading","text":"\xbfPor qu\xe9 acelera la inflaci\xf3n en septiembre de 2026?"},{"id":"b009","kind":"paragraph","text":"Las hortalizas bajan de temporada, pero menos que la semana previa, mientras suben huevos y cereales: los huevos avanzaron un 1,9% en la \xfaltima semana. El Banco de Rusia estima una inflaci\xf3n persistente del 5–6% anualizado, superior a la meta del 4%."},{"id":"b010","kind":"heading","text":"\xbfQu\xe9 son las expectativas de inflaci\xf3n y por qu\xe9 importan para los tipos?"},{"id":"b011","kind":"paragraph","text":"Son el crecimiento de precios que la poblaci\xf3n prev\xe9 para el pr\xf3ximo a\xf1o: un 14,2% en septiembre de 2026. Si espera esa subida, el tipo del 14% apenas frena las compras y no las pospone. Las expectativas altas dificultan que el Banco de Rusia reduzca el tipo."}],"sources":[{"label":"La inflaci\xf3n de la \xfaltima semana fue del 0,12%","url":"https://www.vedomosti.ru/economics/news/2026/09/30/1233212-nedelnaya-inflyatsiya"},{"label":"La inflaci\xf3n rusa acelera al 0,06% semanal","url":"https://www.vedomosti.ru/economics/news/2026/09/23/1231274-inflyatsiya-rossii-uskorilas"},{"label":"Del 22 al 28 de septiembre los precios suben un 0,12% y la inflaci\xf3n anual baja al 6,25%","url":"https://www.interfax.ru/business/1119451"},{"label":"Las expectativas rusas suben al 14,2% en septiembre","url":"https://www.vedomosti.ru/economics/news/2026/09/22/1230887-inflyatsionnie-ozhidaniya"},{"label":"El banco central estima la inflaci\xf3n persistente de agosto en el 5–6%","url":"https://ru.themoscowtimes.com/2026/09/16/tsbr-otsenil-ustoychivuyu-inflyatsiyu-v-avguste-v-diapazone-5-6-a206280"},{"label":"El promedio de tipos m\xe1ximos de diez bancos llega al 13,05%","url":"https://ria.ru/20261001/bank-2121443529.html"},{"label":"El Banco de Rusia mantiene el tipo oficial en el 14%","url":"https://www.cbr.ru/press/keypr/"}],"sourceBodySha256":"a98c31881322940d45b158db2ab6716a039490f89eea6f0ffe309fb1f7594ee1"}')}}]);